 const refreshPages=async(nextDoc,nextFile=file)=>{const arr=nextDoc.getPages().map((p,i)=>({number:i+1,width:Math.round(p.getWidth()),height:Math.round(p.getHeight()),rotation:p.getRotation().angle,text:pageText[i+1]||''}));setPages(arr);setActive(a=>clamp(a,1,arr.length||1));setSelected(s=>s.filter(n=>n<=arr.length));setDoc(nextDoc);setThumbs({});setPreviewImages({});if(nextFile)setFile(nextFile)};
 const openFile=async f=>{if(!f)return;if(f.type&&f.type!=='application/pdf'&&!f.name.toLowerCase().endsWith('.pdf')){setStatus('الاستوديو يستقبل ملفات PDF. حوّل الصورة إلى PDF من أدوات الموقع أولاً.');return}setBusy(true);setProgress(0);setStatus('جاري فتح المستند…');try{const bytes=await f.arrayBuffer();const next=await PDFDocument.load(bytes,{ignoreEncryption:false});setFile(new File([bytes],f.name||'document.pdf',{type:PDF}));setDoc(next);setPages(next.getPages().map((p,i)=>({number:i+1,width:Math.round(p.getWidth()),height:Math.round(p.getHeight()),rotation:p.getRotation().angle,text:''})));setSelected([]);setSelectionMode(false);setPreviewImages({});setThumbs({});setActive(1);setHistory([]);setFuture([]);setAnnotations([]);setAnnotationUndo([]);setAnnotationRedo([]);setCurrentStroke(null);setRedactBoxes([]);strokeRef.current=null;setOcr('');setPageText({});setStatus('تم فتح '+next.getPageCount()+' صفحة. حدد الصفحات وابدأ التعديل.')}catch(e){setStatus('تعذر فتح الملف. قد يكون تالفاً أو محمياً بكلمة مرور. '+e.message)}finally{setBusy(false)}};
