 const movePage=async(dir)=>{const from=active-1,to=clamp(from+dir,0,pageCount-1);if(from===to)return;const next=await loadCurrent();const order=pageList(pageCount);[order[from],order[to]]=[order[to],order[from]];const fresh=await PDFDocument.create();const copied=await fresh.copyPages(next,order.map(n=>n-1));copied.forEach(p=>fresh.addPage(p));await commit(fresh,'تم نقل الصفحة');setActive(to+1)};
 const extract=async()=>{if(!doc)return;const nums=[...new Set(chosen)].sort((a,b)=>a-b);const next=await PDFDocument.create();const copied=await next.copyPages(await loadCurrent(),nums.map(n=>n-1));copied.forEach(p=>next.addPage(p));const blob=new Blob([await next.save()],{type:PDF});download(blob,safeName(file.name)+'-pages.pdf');setStatus('تم تصدير '+nums.length+' صفحة في ملف مستقل')};
