 const applyCrop=async()=>{if(!doc)return;setBusy(true);try{const next=await loadCurrent();const m=cropMargins;for(const n of chosen){const p=next.getPages()[n-1];if(!p)continue;const {width,height}=p.getSize(),l=width*clamp(+m.left||0,0,45)/100,r=width*clamp(+m.right||0,0,45)/100,t=height*clamp(+m.top||0,0,45)/100,b=height*clamp(+m.bottom||0,0,45)/100;if(l+r>=width*.9||t+b>=height*.9)throw Error('مجموع الهوامش كبير جداً');p.setCropBox(l,b,width-l-r,height-t-b)}await commit(next,'تم قص هوامش '+chosen.length+' صفحة')}catch(e){setStatus('تعذر قص الصفحات: '+e.message)}finally{setBusy(false)}};
